/** Highest number ever issued in a project: live rows, archived rows, and numbers retired by a move. */
function highestIssueNumber(
  db: NumberStore,
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const rows = db
    .select({ value: sql<number | null>`max(${issues.number})` })
