      ),
    )
    .get();

  return Math.max(rows?.value ?? 0, mark?.value ?? 0);
}

/** Remembers that `issueNumber` has been used in the project, whatever happens to its row. */
function retireIssueNumber(
  db: NumberStore,
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  db.insert(projectIssueCounters)
    .values({ projectId, orgId, lastNumber: issueNumber })
    .onConflictDoUpdate({
      target: projectIssueCounters.projectId,
      set: {
        lastNumber: sql`max(${projectIssueCounters.lastNumber}, excluded.last_number)`,
      },
    })
    .run();
}

