 * archived issues keep theirs, and one that moved away is remembered by the
 * project's counter, so the answer comes from every number ever used rather
 * than from the rows currently there.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return highestIssueNumber(getDb(), orgId, projectId) + 1;
}

