    retireIssueNumber(tx, orgId, projectId, current.number);

    return tx
      .update(issues)
      .set({ projectId, updatedAt: toIsoTimestamp(new Date()) })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();
  });

  return toIssue(row);
}

/** An issue after `moveIssueToProject`, with the project and number it left. */
export interface MovedIssue {
  readonly issue: Issue;
  readonly fromProjectId: ProjectId;
  readonly fromNumber: number;
}

/**
 * Moves an issue into another project under that project's next number,
 * allocated as `nextIssueNumber` would. The old number is retired in the
 * source project before the row leaves it, and the target's counter follows
 * the new one; all of it happens in one transaction, so a failure leaves
 * the issue and both counters as they were.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<MovedIssue> {
  const { row, fromProjectId, fromNumber } = getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);

    const from = current.projectId as ProjectId;
    if (from === toProjectId) {
      return { row: current, fromProjectId: from, fromNumber: current.number };
    }

    retireIssueNumber(tx, orgId, from, current.number);
    const number = highestIssueNumber(tx, orgId, toProjectId) + 1;

    const moved = tx
      .update(issues)
      .set({
        projectId: toProjectId,
        number,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();

    retireIssueNumber(tx, orgId, toProjectId, number);

    return { row: moved, fromProjectId: from, fromNumber: current.number };
  });

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return {
    issue: toIssue(row, (labels[issueId] ?? []).map((label) => label.id)),
    fromProjectId,
    fromNumber,
  };
}

