  const moved = await issueRepo.moveIssueToProject(
    input.orgId,
    input.issueId,
    target.id,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: moved.issue.id,
    fromProjectId: moved.fromProjectId,
    toProjectId: moved.issue.projectId,
    fromNumber: moved.fromNumber,
    toNumber: moved.issue.number,
  });

  return moved.issue;
}

