/**
 * Moving an issue to another project (ADR 0011): numbering, permissions,
 * quota, the single `issue.moved` event, the audit row and the search index.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { activityActionSchema, activityFilterSchema } from "@/schemas/activity";
import { moveIssueToProjectSchema } from "@/schemas/issue";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let target: Awaited<ReturnType<typeof projectService.createProject>>;
let detachers: Unsubscribe[] = [];

const ALL_ISSUE_EVENTS: readonly TaskflowEventType[] = [
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "issue.archived",
  "issue.moved",
];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers = [
    activityService.registerActivityListeners(),
    searchService.registerSearchListeners(),
  ];
  tenant = await createTenant("moveissue", "growth");
  target = await projectService.createProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    name: "Target",
    slug: "target",
    key: "TGT",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
});

afterAll(() => {
  for (const off of detachers) off();
  cleanup();
});

afterEach(() => {
  vi.restoreAllMocks();
});

async function create(title: string, projectId = tenant.project.id) {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title }),
  );
}

function moveInput(issueId: string, toProjectId = target.id) {
  return moveIssueToProjectSchema.parse({
    orgId: tenant.org.id,
    issueId,
    toProjectId,
  });
}

function capture(...types: readonly TaskflowEventType[]) {
  const seen: { type: string; payload: unknown }[] = [];
  const offs = types.map((type) =>
    subscribe(type, (payload) => {
      seen.push({ type, payload });
    }),
  );
  return { seen, stop: () => offs.forEach((off) => off()) };
}

describe("moveIssueToProject", () => {
  it("joins the target under its next number and keeps every other field", async () => {
    await create("Already in target", target.id);
    const issue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, {
        title: "Wrong project",
        assigneeId: tenant.userIds.admin,
      }),
      description: "details",
      priority: "high",
      estimate: 5,
    });

    const moved = await issueService.moveIssueToProject(
      tenant.actors.member,
      moveInput(issue.id),
    );

    expect(moved).toMatchObject({
      id: issue.id,
      projectId: target.id,
      number: 2,
      title: issue.title,
      description: "details",
      status: issue.status,
      priority: "high",
      assigneeId: tenant.userIds.admin,
      estimate: 5,
      dueAt: issue.dueAt,
      authorId: issue.authorId,
      createdAt: issue.createdAt,
    });
    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toEqual(moved);
  });

  it("never reissues a retired number, moving away, back, or creating afterwards", async () => {
    const source = await createTenant("movenumbers", "growth");
    const other = await projectService.createProject(source.actors.admin, {
      orgId: source.org.id,
      name: "Other",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const make = (projectId: typeof other.id) =>
      issueService.createIssue(
        source.actors.member,
        issueInput(source.org.id, projectId, { title: "numbered" }),
      );

    const first = await make(source.project.id);
    const second = await make(source.project.id);
    expect([first.number, second.number]).toEqual([1, 2]);

    const away = await issueService.moveIssueToProject(source.actors.member, {
      orgId: source.org.id,
      issueId: second.id,
      toProjectId: other.id,
    });
    expect(away.number).toBe(1);

    // The source continues after the highest number it ever issued.
    expect((await make(source.project.id)).number).toBe(3);

    const back = await issueService.moveIssueToProject(source.actors.member, {
      orgId: source.org.id,
      issueId: second.id,
      toProjectId: source.project.id,
    });
    expect(back.number).toBe(4);
    expect((await make(other.id)).number).toBe(2);
  });

  it("publishes exactly one issue.moved, on behalf of the mover, and nothing else", async () => {
    const issue = await create("Announce me");
    const { seen, stop } = capture(...ALL_ISSUE_EVENTS);

    try {
      await issueService.moveIssueToProject(tenant.actors.member, moveInput(issue.id));
    } finally {
      stop();
    }

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      type: "issue.moved",
      payload: {
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        issueId: issue.id,
        fromProjectId: tenant.project.id,
        toProjectId: target.id,
        fromNumber: issue.number,
      },
    });
  });

  it("records one audit row under the target project, leaving earlier rows alone", async () => {
    const issue = await create("Audited move");
    const before = await activityRepo.listActivityForSubject(tenant.org.id, "issue", issue.id);
    expect(before.map((row) => row.projectId)).toEqual([tenant.project.id]);

    const moved = await issueService.moveIssueToProject(
      tenant.actors.member,
      moveInput(issue.id),
    );

    const page = await activityService.listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["issue.moved"],
      subjectKind: "issue",
      limit: 25,
      cursor: null,
    });
    const rows = page.items.filter((row) => row.subjectId === issue.id);
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      action: "issue.moved",
      actorId: tenant.userIds.member,
      subjectKind: "issue",
      projectId: target.id,
      metadata: {
        fromProjectId: tenant.project.id,
        toProjectId: target.id,
        fromNumber: issue.number,
        toNumber: moved.number,
      },
    });

    const after = await activityRepo.listActivityForSubject(tenant.org.id, "issue", issue.id);
    expect(after.filter((row) => row.action === "issue.created")).toMatchObject([
      { projectId: tenant.project.id },
    ]);
  });

  it("moves the issue between the two projects' search results", async () => {
    const issue = await create("Quokka migration marker");
    const search = (projectId: typeof target.id) =>
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "Quokka migration marker",
        kinds: ["issue"],
        projectId,
        limit: 25,
        cursor: null,
      });

    expect((await search(tenant.project.id)).total).toBe(1);
    await issueService.moveIssueToProject(tenant.actors.member, moveInput(issue.id));
    expect((await search(tenant.project.id)).total).toBe(0);
    expect((await search(target.id)).items.map((hit) => hit.id)).toEqual([issue.id]);
  });

  it("lists the issue in the target's board and out of the source's", async () => {
    const issue = await create("Board follower");
    await issueService.moveIssueToProject(tenant.actors.member, moveInput(issue.id));

    const ids = async (projectId: typeof target.id) =>
      (await issueService.getBoard(tenant.actors.member, tenant.org.id, projectId))
        .flatMap((column) => column.issues)
        .map((row) => row.id);

    expect(await ids(target.id)).toContain(issue.id);
    expect(await ids(tenant.project.id)).not.toContain(issue.id);
  });

  it("is a silent no-op within the same project", async () => {
    const issue = await create("Stay put");
    const { seen, stop } = capture(...ALL_ISSUE_EVENTS);

    try {
      const result = await issueService.moveIssueToProject(
        tenant.actors.member,
        moveInput(issue.id, tenant.project.id),
      );
      expect(result).toEqual(issue);
    } finally {
      stop();
    }

    expect(seen).toEqual([]);
    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toEqual(issue);
  });

  it("needs issue:update on the issue and issue:create in the target", async () => {
    const issue = await create("Guarded");
    const { seen, stop } = capture("issue.moved");

    try {
      await expect(
        issueService.moveIssueToProject(tenant.actors.viewer, moveInput(issue.id)),
      ).rejects.toBeInstanceOf(PermissionDeniedError);

      // An author may edit their own issue, but without issue:create the
      // target is still closed to them.
      const viewerAuthored = await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: "Viewer's own" }),
        tenant.userIds.viewer,
        await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id),
      );
      await expect(
        issueService.moveIssueToProject(tenant.actors.viewer, moveInput(viewerAuthored.id)),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
      await expect(
        issueRepo.findIssueById(tenant.org.id, viewerAuthored.id),
      ).resolves.toMatchObject({ projectId: tenant.project.id });
    } finally {
      stop();
    }

    expect(seen).toEqual([]);
    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toMatchObject({
      projectId: tenant.project.id,
      number: issue.number,
    });
  });

  it("refuses a target at its plan quota and changes nothing", async () => {
    const free = await createTenant("movequota", "free");
    const full = await projectService.createProject(free.actors.admin, {
      orgId: free.org.id,
      name: "Full",
      slug: "full",
      key: "FUL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(free.org.id, full.id, { title: `Seed ${number}` }),
        free.userIds.member,
        number,
      );
    }
    const issue = await issueService.createIssue(
      free.actors.member,
      issueInput(free.org.id, free.project.id, { title: "Does not fit" }),
    );

    await expect(
      issueService.moveIssueToProject(free.actors.member, {
        orgId: free.org.id,
        issueId: issue.id,
        toProjectId: full.id,
      }),
    ).rejects.toThrow(/allows no more issues/);

    await expect(issueRepo.findIssueById(free.org.id, issue.id)).resolves.toEqual(issue);
    await expect(issueRepo.nextIssueNumber(free.org.id, free.project.id)).resolves.toBe(2);
  });

  it("refuses a project of another workspace or an archived one", async () => {
    const stranger = await createTenant("movestranger", "growth");
    const issue = await create("Stays home");

    await expect(
      issueService.moveIssueToProject(tenant.actors.member, moveInput(issue.id, stranger.project.id)),
    ).rejects.toMatchObject({ code: "not_found" });

    const archived = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Archived",
      slug: "archived-target",
      key: "ARC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: archived.id,
      archiveIssues: false,
    });
    await expect(
      issueService.moveIssueToProject(tenant.actors.member, moveInput(issue.id, archived.id)),
    ).rejects.toMatchObject({ code: "conflict" });

    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toMatchObject({
      projectId: tenant.project.id,
    });
  });
});

describe("audit action issue.moved", () => {
  it("is accepted by the audit-log filter schema", () => {
    expect(activityActionSchema.safeParse("issue.moved").success).toBe(true);
    expect(
      activityFilterSchema.safeParse({
        orgId: tenant.org.id,
        action: ["issue.moved"],
        limit: 25,
        cursor: null,
      }).success,
    ).toBe(true);
  });
});

