/**
 * Moving an issue to another project (ADR 0011): numbering, permissions,
 * quota, the single `issue.moved` event, the audit row and the search index.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { activityActionSchema, activityFilterSchema } from "@/schemas/activity";
import { moveIssueToProjectSchema } from "@/schemas/issue";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let target: Awaited<ReturnType<typeof projectService.createProject>>;
let detachers: Unsubscribe[] = [];

const ALL_ISSUE_EVENTS: readonly TaskflowEventType[] = [
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "issue.archived",
  "issue.moved",
];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers = [
    activityService.registerActivityListeners(),
    searchService.registerSearchListeners(),
  ];
  tenant = await createTenant("moveissue", "growth");
  target = await projectService.createProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    name: "Target",
    slug: "target",
    key: "TGT",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
});

afterAll(() => {
  for (const off of detachers) off();
  cleanup();
});

afterEach(() => {
  vi.restoreAllMocks();
});

async function create(title: string, projectId = tenant.project.id) {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title }),
  );
}

function moveInput(issueId: string, toProjectId = target.id) {
  return moveIssueToProjectSchema.parse({
    orgId: tenant.org.id,
    issueId,
    toProjectId,
  });
}

function capture(...types: readonly TaskflowEventType[]) {
  const seen: { type: string; payload: unknown }[] = [];
  const offs = types.map((type) =>
    subscribe(type, (payload) => {
      seen.push({ type, payload });
    }),
  );
  return { seen, stop: () => offs.forEach((off) => off()) };
}

describe("moveIssueToProject", () => {
  it("joins the target under its next number and keeps every other field", async () => {
    await create("Already in target", target.id);
    const issue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, {
        title: "Wrong project",
        assigneeId: tenant.userIds.admin,
      }),
      description: "details",
      priority: "high",
      estimate: 5,
    });

    const moved = await issueService.moveIssueToProject(
      tenant.actors.member,
      moveInput(issue.id),
    );

    expect(moved).toMatchObject({
      id: issue.id,
      projectId: target.id,
      number: 2,
      title: issue.title,
      description: "details",
      status: issue.status,
      priority: "high",
      assigneeId: tenant.userIds.admin,
      estimate: 5,
      dueAt: issue.dueAt,
