    const first = await make(source.project.id);
    const second = await make(source.project.id);
    expect([first.number, second.number]).toEqual([1, 2]);

    const away = await issueService.moveIssueToProject(source.actors.member, {
      orgId: source.org.id,
      issueId: second.id,
      toProjectId: other.id,
    });
    expect(away.number).toBe(1);

    // The source continues after the highest number it ever issued.
    expect((await make(source.project.id)).number).toBe(3);

    const back = await issueService.moveIssueToProject(source.actors.member, {
      orgId: source.org.id,
      issueId: second.id,
      toProjectId: source.project.id,
    });
    expect(back.number).toBe(4);
    expect((await make(other.id)).number).toBe(2);
