        tenant.userIds.viewer,
        await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id),
      );
      await expect(
        issueService.moveIssueToProject(tenant.actors.viewer, moveInput(viewerAuthored.id)),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
      await expect(
        issueRepo.findIssueById(tenant.org.id, viewerAuthored.id),
      ).resolves.toMatchObject({ projectId: tenant.project.id });
    } finally {
      stop();
    }

    expect(seen).toEqual([]);
    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toMatchObject({
      projectId: tenant.project.id,
      number: issue.number,
    });
  });

  it("refuses a target at its plan quota and changes nothing", async () => {
    const free = await createTenant("movequota", "free");
    const full = await projectService.createProject(free.actors.admin, {
      orgId: free.org.id,
      name: "Full",
      slug: "full",
      key: "FUL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(free.org.id, full.id, { title: `Seed ${number}` }),
        free.userIds.member,
        number,
      );
    }
    const issue = await issueService.createIssue(
      free.actors.member,
      issueInput(free.org.id, free.project.id, { title: "Does not fit" }),
    );

    await expect(
      issueService.moveIssueToProject(free.actors.member, {
        orgId: free.org.id,
        issueId: issue.id,
        toProjectId: full.id,
      }),
    ).rejects.toThrow(/allows no more issues/);

    await expect(issueRepo.findIssueById(free.org.id, issue.id)).resolves.toEqual(issue);
    await expect(issueRepo.nextIssueNumber(free.org.id, free.project.id)).resolves.toBe(2);
  });

  it("refuses a project of another workspace or an archived one", async () => {
    const stranger = await createTenant("movestranger", "growth");
    const issue = await create("Stays home");

    await expect(
      issueService.moveIssueToProject(tenant.actors.member, moveInput(issue.id, stranger.project.id)),
    ).rejects.toMatchObject({ code: "not_found" });

    const archived = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Archived",
      slug: "archived-target",
      key: "ARC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: archived.id,
